Definition glp_rows (data wpl : Z) (n : nat) : list word := map (fun j => Z_to_bv 64 (data + 4 * wpl * Z.of_nat j)) (seq 0 n).
Lemma glp_rows_S : forall data wpl n, glp_rows data wpl (S n) = glp_rows data wpl n ++ [Z_to_bv 64 (data + 4 * wpl * Z.of_nat n)].
Proof.
ltac2:(KReplay.run1 (kr_t_Bi_lineptrs_loop ()) [] "h01jh11lh24datah31nh43wplp;1p;2p;3p;4p;5p;6g0000R0p4p7210g000LR1p4p710p8g000jj1=Tg001Jj27Tg001fj2ATg002=j1:Tg002]j38Tg003=j33Tg003Zj11Tg004?j1@Tg004]j1?Tg005@j1>Tg005^j20Tg006;j19Tg006[j25Tg0078j24Tg007^j42Tg008:j36Tg008Tj2ETP0j5DTP1j6<Tg008nj1CTg009Mj2BTg009gj3;Tg00:lR1g00;JR0%=0R2g00;iR3f0R4'7R51A34%:0580R6530R7g00<H#1#1R8#1#1#1#1#@R9#?R:#=R;P0P:f4%>8R8f3R<'0%94R='0'5,49X00R>P4C2P0P:P>f1R>,73C2f2R?,08R@%9>'0,5<,49%::RA58:53:RB36X12P;P0P:10@=,5<,49X00R<P5C2R@P0P:P<P6C253:A6;4BX1;108>/0=,5?,49=8:ARA93:@,E;P0P:P<P7C2P0P:P<P5P6DDE<%C4R6,731B43E<A;?>6A;?>4=3:A56;eW3X41W2o"). Qed.
Lemma glp_rows_length : forall data wpl n, length (glp_rows data wpl n) = n.
Proof.
ltac2:(KReplay.run1 (kr_t_Bi_lineptrs_loop ()) [] "h01nh14datah21jh33wplp;2p;3p;6p;1p;4g001Jj2@Tg00<mj21Tg008:j32Tg008Tj25Tg00=Mj2?Tg000Lj64Tg003Zj10Tg004?j18Tg004]j17Tg005@j16Tg005^j23Tg006;j19Tg006[j2:Tg0078j2>Tg007^j4=Tg00=lj4<Tg009gj3;Tg00:lR0g00;JR1P1g00;iR2f0R3'@R4,11R5f1R69213X01R7P1P3P71513P51?32E4g00<H#0#0R2#0#0#0#0#8R5#7R7P1P7f3%62f2R2'3%93'3':,>5X21R5P4C='1P1P7P5P4C<E4A;263,17=213eW0X30W1o"). Qed.

(* [comment removed for export] *)
Definition glp_exit (ra sp gp tp t0 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lp data wpl h : Z) : machine_state -> Prop :=
  fun ms' => exists (t1' t2' a1' a2' a3' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1' t2' s0 s1 (Z_to_bv 64 lp) a1' a2' a3' a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x9d40c) fc None m' (seg_rom asegs)
    /\ munch [(lp, lp + 8 * h)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ u64arr asegs m' lp (glp_rows data wpl (Z.to_nat h)).

Lemma glp_loop : forall (k : nat) (i : Z)
    (ra sp gp tp t1 t2 s0 a1 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem) (lp data wpl h : Z),
  Z.of_nat k = h - i -> 0 <= i -> (1 <= k)%nat -> 0 < h <= 20000 -> 0 < wpl <= 2^20 -> wpl * h <= 2^24 -> 0 < data -> data + 4 * wpl * h <= 2^47 ->
  0 < lp -> lp mod 8 = 0 -> lp + 8 * h <= 2^47 -> (lp + 8 * h <= 0x7fff7000 \/ 0x10007fff8000 <= lp) ->
